result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "where_eval.py", "content": """"Parser and evaluator for SQL WHERE clauses over in-memory rows.

Public API:
    filter_rows(clause: str, rows: list[dict]) -> list[dict]

Stdlib only. Supports:
    =, !=, <, <=, >, >=
    AND, OR, NOT (precedence: NOT > AND > OR)
    parentheses
    IN (list), [NOT] BETWEEN x AND y
    LIKE with % and _ wildcards
    IS NULL / IS NOT NULL
    single-quoted string literals with '' escaping, numeric literals

Syntax errors report the offending token and its position.
"""

from __future__ import annotations

import re
from typing import Any, Callable


class WhereSyntaxError(ValueError):
    """Raised when a WHERE clause cannot be parsed."""

    def __init__(self, message: str, token: str | None = None, pos: int | None = None):
        self.token = token
        self.pos = pos
        if token is not None and pos is not None:
            message = f"{message} (offending token {token!r} at position {pos})"
        super().__init__(message)


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

_TWO_CHAR_OPS = ("<=", ">=", "!=", "<>")
_ONE_CHAR_OPS = ("=", "<", ">", "(", ")", ",")


class Token:
    __slots__ = ("kind", "value", "pos")

    def __init__(self, kind: str, value: Any, pos: int):
        self.kind = kind      # 'IDENT', 'NUMBER', 'STRING', 'OP', 'EOF'
        self.value = value
        self.pos = pos        # index in the original clause string

    def __repr__(self):  # pragma: no cover - debugging aid
        return f"Token({self.kind}, {self.value!r}, {self.pos})"


def tokenize(clause: str) -> list[Token]:
    tokens: list[Token] = []
    i, n = 0, len(clause)
    while i < n:
        ch = clause[i]
        if ch.isspace():
            i += 1
            continue
        if clause[i : i + 2] in _TWO_CHAR_OPS:
            op = "<>" if clause[i : i + 2] == "<>" else clause[i : i + 2]
            tokens.append(Token("OP", op, i))
            i += 2
            continue
        if ch in _ONE_CHAR_OPS:
            tokens.append(Token("OP", ch, i))
            i += 1
            continue
        if ch == "'":
            start = i
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise WhereSyntaxError("unterminated string literal", "'", start)
                c = clause[i]
                if c == "'":
                    if i + 1 < n and clause[i + 1] == "'":  # '' escape
                        buf.append("'")
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    buf.append(c)
                    i += 1
            tokens.append(Token("STRING", "".join(buf), start))
            continue
        if ch.isdigit() or (ch == "." and i + 1 < n and clause[i + 1].isdigit()):
            m = re.match(r"\d+(?:\.\d+)?|\.\d+", clause[i:])
            text = m.group(0)
            value = float(text) if "." in text else int(text)
            tokens.append(Token("NUMBER", value, i))
            i += len(text)
            continue
        if ch.isalpha() or ch == "_":
            m = re.match(r"[A-Za-z_][A-Za-z_0-9]*", clause[i:])
            text = m.group(0)
            tokens.append(Token("IDENT", text, i))
            i += len(text)
            continue
        raise WhereSyntaxError("unexpected character", ch, i)
    tokens.append(Token("EOF", None, n))
    return tokens


# ---------------------------------------------------------------------------
# Parser (recursive descent) producing an AST of callables
#
# AST nodes are closures row -> bool.
# ---------------------------------------------------------------------------

_KEYWORDS = {"AND", "OR", "NOT", "IN", "BETWEEN", "LIKE", "IS", "NULL"}


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.i = 0

    # -- helpers ----------------------------------------------------------
    @property
    def cur(self) -> Token:
        return self.tokens[self.i]

    def advance(self) -> Token:
        tok = self.tokens[self.i]
        self.i += 1
        return tok

    def at_op(self, *ops: str) -> bool:
        return self.cur.kind == "OP" and self.cur.value in ops

    def at_kw(self, word: str) -> bool:
        return (
            self.cur.kind == "IDENT"
            and self.cur.value.upper() == word
        )

    def eat_kw(self, word: str) -> None:
        """Consume keyword `word` or raise."""
        if self.at_kw(word):
            self.advance()
        else:
            t = self.cur
            shown = repr(t.value) if t.kind != "EOF" else "end of input"
            raise WhereSyntaxError(
                f"expected {word}", t.value if t.kind != "EOF" else "<end of input>", t.pos
            )

    def eat_op(self, op: str) -> None:
        if self.at_op(op):
            self.advance()
        else:
            t = self.cur
            raise WhereSyntaxError(f"expected {op!r}", t.value if t.kind != "EOF" else "<end of input>", t.pos)

    def unexpected(self, context: str) -> WhereSyntaxError:
        t = self.cur
        name = "<end of input>" if t.kind == "EOF" else str(t.value)
        return WhereSyntaxError(f"unexpected {name} in {context}", t.value if t.kind != "EOF" else name, t.pos)

    # -- grammar ----------------------------------------------------------
    # or_expr  := and_expr (OR and_expr)*
    # and_expr := not_expr (AND not_expr)*
    # not_expr := NOT not_expr | predicate
    # predicate:= '(' or_expr ')'
    #           | operand comp_op operand
    #           | operand [NOT] IN '(' literal (',' literal)* ')'
    #           | operand [NOT] BETWEEN operand AND operand
    #           | operand LIKE operand
    #           | operand IS [NOT] NULL
    # operand  := NUMBER | STRING | NULL | IDENT

    def parse(self) -> Callable[[dict], bool]:
        node = self.or_expr()
        t = self.cur
        if t.kind != "EOF":
            raise WhereSyntaxError("unexpected trailing input", t.value, t.pos)
        return node

    def or_expr(self):
        left = self.and_expr()
        while self.at_kw("OR"):
            self.advance()
            right = self.and_expr()
            l, r = left, right
            left = lambda row, l=l, r=r: l(row) or r(row)
        return left

    def and_expr(self):
        left = self.not_expr()
        while self.at_kw("AND"):
            self.advance()
            right = self.not_expr()
            l, r = left, right
            left = lambda row, l=l, r=r: l(row) and r(row)
        return left

    def not_expr(self):
        if self.at_kw("NOT"):
            tok = self.advance()
            inner = self.not_expr()
            return lambda row, inner=inner, tok=tok: not inner(row)
        return self.predicate()

    def predicate(self):
        if self.at_op("("):
            self.advance()
            node = self.or_expr()
            self.eat_op(")")
            return node
        lhs = self.operand()
        if self.at_kw("NOT"):
            self.advance()
            if self.at_kw("IN"):
                return self.in_predicate(lhs, negated=True)
            if self.at_kw("BETWEEN"):
                return self.between_predicate(lhs, negated=True)
            if self.at_kw("LIKE"):
                return self.like_predicate(lhs, negated=True)
            raise self.unexpected("NOT (expected IN, BETWEEN or LIKE)")
        if self.at_kw("IN"):
            return self.in_predicate(lhs, negated=False)
        if self.at_kw("BETWEEN"):
            return self.between_predicate(lhs, negated=False)
        if self.at_kw("LIKE"):
            return self.like_predicate(lhs, negated=False)
        if self.at_kw("IS"):
            return self.is_null_predicate(lhs)
        if self.at_op("=", "!=", "<>", "<", "<=", ">", ">="):
            op_tok = self.advance()
            rhs = self.operand()
            op = op_tok.value
            if op == "<>":
                op = "!="
            return self._comparison(lhs, op, rhs, op_tok)
        raise self.unexpected("predicate")

    def _comparison(self, lhs, op, rhs, tok):
        ops = {
            "=": lambda a, b: a == b,
            "!=": lambda a, b: a != b,
            "<": lambda a, b: isinstance(a, (int, float)) and isinstance(b, (int, float)) and a < b,
            "<=": lambda a, b: isinstance(a, (int, float)) and isinstance(b, (int, float)) and a <= b,
            ">": lambda a, b: isinstance(a, (int, float)) and isinstance(b, (int, float)) and a > b,
            ">=": lambda a, b: isinstance(a, (int, float)) and isinstance(b, (int, float)) and a >= b,
        }

        def node(row):
            a, b = lhs(row), rhs(row)
            if a is None or b is None:
                return False  # SQL semantics: comparison with NULL is not true
            try:
                return ops[op](a, b)
            except TypeError:
                return False

        return node

    def in_predicate(self, lhs, negated):
        self.eat_kw("IN")
        self.eat_op("(")
        items = []
        while True:
            items.append(self.operand())
            if self.at_op(","):
                self.advance()
                continue
            break
        self.eat_op(")")

        def contains(row):
            v = lhs(row)
            for item in items:
                w = item(row)
                if v is not None and v == w:
                    return True
            return False

        return (lambda row: not contains(row)) if negated else contains

    def between_predicate(self, lhs, negated):
        self.eat_kw("BETWEEN")
        low = self.operand()
        self.eat_kw("AND")
        high = self.operand()

        def in_range(row):
            v, lo, hi = lhs(row), low(row), high(row)
            if v is None or lo is None or hi is None:
                return False
            if not all(isinstance(x, (int, float)) for x in (v, lo, hi)):
                return False
            return lo <= v <= hi

        return (lambda row: not in_range(row)) if negated else in_range

    def like_predicate(self, lhs, negated):
        self.eat_kw("LIKE")
        pattern_node = self.operand()
        cache: dict[str, re.Pattern] = {}

        def matches(row):
            v = lhs(row)
            pat = pattern_node(row)
            if not isinstance(v, str) or not isinstance(pat, str):
                return False
            rx = cache.get(pat)
            if rx is None:
                parts = []
                for c in pat:
                    if c == "%":
                        parts.append(".*")
                    elif c == "_":
                        parts.append(".")
                    else:
                        parts.append(re.escape(c))
                rx = re.compile("^" + "".join(parts) + "$", re.DOTALL)
                cache[pat] = rx
            return rx.match(v) is not None

        return (lambda row: not matches(row)) if negated else matches

    def is_null_predicate(self, lhs):
        tok = self.advance()
        negated = False
        if self.at_kw("NOT"):
            self.advance()
            negated = True
        null_tok_pos = tok.pos
        if not self.at_kw("NULL"):
            raise WhereSyntaxError("expected NULL after IS", self.cur.value, self.cur.pos)
        self.advance()
        if negated:
            return lambda row: lhs(row) is not None
        return lambda row: lhs(row) is None

    def operand(self):
        t = self.cur
        if t.kind == "NUMBER":
            self.advance()

            def const(row, v=t.value):
                return v

            return const
        if t.kind == "STRING":
            self.advance()
            return lambda row, v=t.value: v
        if t.kind == "IDENT":
            upper = t.value.upper()
            if upper == "NULL":
                self.advance()
                return lambda row: None
            if upper in _KEYWORDS:
                raise WhereSyntaxError(
                    f"unexpected keyword {t.value!r} where a value was expected",
                    t.value,
                    t.pos,
                )
            self.advance()
            col_name, col_pos = t.value, t.pos

            def colref(row, name=col_name, pos=col_pos):
                if name not in row:
                    raise KeyError(
                        f"unknown column {name!r} (referenced at position {pos})"
                    )
                return row[name]

            return colref
        raise self.unexpected("operand")


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

_cache: dict[str, Callable[[dict], bool]] = {}


def compile_clause(clause: str) -> Callable[[dict], bool]:
    ast = _cache.get(clause)
    if ast is None:
        ast = Parser(tokenize(clause)).parse()
        _cache[clause] = ast
    return ast


def filter_rows(clause: str, rows: list[dict]) -> list[dict]:
    """Return the rows for which `clause` evaluates to true."""
    pred = compile_clause(clause)
    out = []
    for row in rows:
        try:
            keep = pred(row)
        except KeyError as exc:
            raise KeyError(f"{exc.args[0]}; available columns: {sorted(row)}") from exc
        if keep:
            out.append(row)
    return out
